"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[87302],{13191:(e,t,s)=>{s.r(t),s.d(t,{assets:()=>a,contentTitle:()=>o,default:()=>c,frontMatter:()=>h,metadata:()=>r,toc:()=>l});var n=s(31085),i=s(71184);const h={sidebar_position:49,slug:"/bible/Genesis/Genesis_49",title:"Genesis 49",hide_table_of_contents:!0},o="Genesis",r={id:"bible/Genesis/Genesis 49",title:"Genesis 49",description:"Chapter 49",source:"@site/docs/bible/Genesis/Genesis 49.md",sourceDirName:"bible/Genesis",slug:"/bible/Genesis/Genesis_49",permalink:"/bibleNotes/docs/bible/Genesis/Genesis_49",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Genesis/Genesis 49.md",tags:[],version:"current",sidebarPosition:49,frontMatter:{sidebar_position:49,slug:"/bible/Genesis/Genesis_49",title:"Genesis 49",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Genesis 48",permalink:"/bibleNotes/docs/bible/Genesis/Genesis_48"},next:{title:"Genesis 50",permalink:"/bibleNotes/docs/bible/Genesis/Genesis_50"}},a={},l=[{value:"Chapter 49",id:"chapter-49",level:2}];function d(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,i.R)(),...e.components},{BibleText:s}=t;return s||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"genesis",children:"Genesis"}),"\n",(0,n.jsx)(t.h2,{id:"chapter-49",children:"Chapter 49"}),"\n",(0,n.jsx)(t.p,{children:"Jacob's prophetical blessings of his twelve sons:  his death."}),"\n",(0,n.jsx)(s,{verse:1,children:"And Jacob called his sons, and said to them: Gather yourselves together, that I may tell you the things that shall befall you in the last days."}),"\n",(0,n.jsx)(s,{verse:2,children:"Gather yourselves together, and hear, O ye sons of Jacob, hearken to Israel, your father:"}),"\n",(0,n.jsx)(s,{verse:3,children:"Ruben, my firstborn, thou art my strength, and the beginning of my sorrow; excelling in gifts, greater in command."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: My strength, etc...He calls him his strength, as being born whilst his father was in his full strength and vigour: he calls him the beginning of his sorrow, because cares and sorrows usually come on with the birth of children. Excelling in gifts, etc., because the firstborn had a title to a double portion, and to have the command over his brethren, which Ruben forfeited by his sin; being poured out as water, that is, spilt and lost."})}),"\n",(0,n.jsx)(s,{verse:4,children:"Thou art poured out as water, grow thou not; because thou wentest up to thy father's bed, and didst defile his couch."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Grow thou not...This was not meant by way of a curse or imprecation; but by way of a prophecy foretelling that the tribe of Ruben should not inherit the pre-eminences usually annexed to the first birthright, viz., the double portion, the being prince or lord over the other brethren, and the priesthood: of which the double portion was given to Joseph, the princely office to Juda, and the priesthood to Levi."})}),"\n",(0,n.jsx)(s,{verse:5,children:"Simeon and Levi brethren: vessels of iniquity waging war."}),"\n",(0,n.jsx)(s,{verse:6,children:"Let not my soul go into their counsel, nor my glory be in their assembly: because in their fury they slew a man, and in their self-will they undermined a wall."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Slew a man,...viz., Sichem the son of Hemor, with all his people, Gen. 34.; mystically and prophetically it alludes to Christ, whom their posterity, viz., the priests and the scribes, put to death."})}),"\n",(0,n.jsx)(s,{verse:7,children:"Cursed be their fury, because it was stubborn: and their wrath, because it was cruel: I will divide them in Jacob, and will scatter them in Israel."}),"\n",(0,n.jsx)(s,{verse:8,children:"Juda, thee shall thy brethren praise: thy hand shall be on the necks of thy enemies; the sons of thy father shall bow down to thee."}),"\n",(0,n.jsx)(s,{verse:9,children:"Juda is a lion's whelp: to the prey, my son, thou art gone up: resting thou hast couched as a lion, and as a lioness, who shall rouse him?"}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: A lion's whelp, etc...This blessing of Juda foretelleth the strength of his tribe, the fertility of his inheritance; and principally that the sceptre and legislative power should not be utterly taken away from his race till about the time of the coming of Christ: as in effect it never was: which is a demonstration against the modern Jews, that the Messiah is long since come; for the sceptre has long since been utterly taken away from Juda."})}),"\n",(0,n.jsx)(s,{verse:10,children:"The sceptre shall not be taken away from Juda, nor a ruler from his thigh, till he come that is to be sent, and he shall be the expectation of nations."}),"\n",(0,n.jsx)(s,{verse:11,children:"Tying his foal to the vineyard, and his ass, O my son, to the vine. He shall wash his robe in wine, and his garment in the blood of the grape."}),"\n",(0,n.jsx)(s,{verse:12,children:"His eyes are more beautiful than wine, and his teeth whiter than milk."}),"\n",(0,n.jsx)(s,{verse:13,children:"Zabulon shall dwell on the seashore, and in the road of ships, reaching as far as Sidon."}),"\n",(0,n.jsx)(s,{verse:14,children:"Issachar shall be a strong ass, lying down between the borders."}),"\n",(0,n.jsx)(s,{verse:15,children:"He saw rest that it was good: and the land that it was excellent: and he bowed his shoulder to carry, and became a servant under tribute."}),"\n",(0,n.jsx)(s,{verse:16,children:"Dan shall judge his people like another tribe in Israel."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Dan shall judge, etc...This was verified in Samson, who was of the tribe of Dan, and began to deliver Israel. Judges 13.5. But as this deliverance was but temporal and very imperfect, the holy patriarch (ver. 18) aspires after another kind of deliverer, saying: I will look for thy salvation, O Lord."})}),"\n",(0,n.jsx)(s,{verse:17,children:"Let Dan be a snake in the way, a serpent in the path, that biteth the horse's heels, that his rider may fall backward."}),"\n",(0,n.jsx)(s,{verse:18,children:"I will look for thy salvation, O Lord."}),"\n",(0,n.jsx)(s,{verse:19,children:"Gad, being girded, shall fight before him: and he himself shall be girded backward."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Gad being girded, etc...It seems to allude to the tribe of Gad; when after they had received for their lot the land of Galaad, they marched in arms before the rest of the Israelites, to the conquest of the land of Chanaan: from whence they afterwards returned loaded with spoils. See Jos. 4. and 12."})}),"\n",(0,n.jsx)(s,{verse:20,children:"Aser, his bread shall be fat, and he shall yield dainties to kings."}),"\n",(0,n.jsx)(s,{verse:21,children:"Nephthali, a hart let loose, and giving words of beauty."}),"\n",(0,n.jsx)(s,{verse:22,children:"Joseph is a growing son, a growing son and comely to behold: the daughters run to and fro upon the wall;"}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Run to and fro, etc...To behold his beauty; whilst his envious brethren turned their darts against him, etc."})}),"\n",(0,n.jsx)(s,{verse:23,children:"But they that held darts, provoked him, and quarrelled with him, and envied him."}),"\n",(0,n.jsx)(s,{verse:24,children:"His bow rested upon the strong, and the bands of his arms and his hands were loosed, by the hands of the mighty one of Jacob: thence he came forth a pastor, the stone of Israel."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: His bow rested upon the strong, etc...That is, upon God, who was his strength: who also loosed his bands, and brought him out of prison to be the pastor, that is, the feeder and ruler of Egypt, and the stone, that is, the rock and support of Israel."})}),"\n",(0,n.jsx)(s,{verse:25,children:"The God of thy father shall be thy helper, and the Almighty shall bless thee with the blessings of heaven above, with the blessings of the deep that lieth beneath, with the blessings of the breasts and of the womb."}),"\n",(0,n.jsx)(s,{verse:26,children:"The blessings of thy father are strengthened with the blessings of his fathers: until the desire of the everlasting hills should come: may they be upon the head of Joseph, and upon the crown of the Nazarite among his brethren."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: The blessings of thy father, etc...That is, thy father's blessings are made more prevalent and effectual in thy regard, by the additional strength they receive from his inheriting the blessings of his progenitors Abraham and Isaac. The desire of the everlasting hills,\r\nNote 2: etc...These blessings all looked forward towards Christ, called the desire of the everlasting hills, as being longed for, as it were, by the whole creation. Mystically, the patriarchs and prophets are called the everlasting hills, by reason of the eminence of their wisdom and\r\nNote 3: holiness. The Nazarite...This word signifies one separated; and agrees to Joseph, as being separated from, and more eminent than, his brethren. As the ancient Nazarites were so called from their being set aside for God, and vowed to him."})}),"\n",(0,n.jsx)(s,{verse:27,children:"Benjamin a ravenous wolf, in the morning shall eat the prey, and in the evening shall divide the spoil."}),"\n",(0,n.jsx)(s,{verse:28,children:"All these are the twelve tribes of Israel: these things their father spoke to them, and he blessed every one with their proper blessings."}),"\n",(0,n.jsx)(s,{verse:29,children:"And he charged them, saying: I am now going to be gathered to my people: bury me with my fathers in the double cave, which is in the field of Ephron the Hethite,"}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: To be gathered to my people...That is, I am going to die, and so to follow my ancestors that are gone before me, and to join their company in another world."})}),"\n",(0,n.jsx)(s,{verse:30,children:"Over against Mambre, in the land of Chanaan, which Abraham bought together with the field, of Ephron the Hethite, for a possession to bury in."}),"\n",(0,n.jsx)(s,{verse:31,children:"There they buried him, and Sara his wife: there was Isaac buried with Rebecca, his wife: there also Lia doth lie buried."}),"\n",(0,n.jsx)(s,{verse:32,children:"And when he had ended the commandments, wherewith he instructed his sons, he drew up his feet upon the bed, and died: and he was gathered to his people."})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},71184:(e,t,s)=>{s.d(t,{R:()=>o,x:()=>r});var n=s(14041);const i={},h=n.createContext(i);function o(e){const t=n.useContext(h);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),n.createElement(h.Provider,{value:t},e.children)}}}]);